+/** Chooses a supported language by quality and header order, or uses the fallback. */
+export function negotiateLanguage(header, fallback = "en") {
+  if (typeof header !== "string") return fallback;
+  let language = fallback;
+  let bestQuality = 0;
+  for (const range of header.split(",")) {
+    const [tag, ...parameters] = range.trim().toLowerCase().split(";");
+    if (!/^(en|ko)(-[a-z0-9]{1,8})*$/.test(tag.trim())) continue;
+    let quality = 1;
+    for (const parameter of parameters) {
+      const match = /^q\s*=\s*(.*)$/.exec(parameter.trim());
+      if (match) quality = /^(0(?:\.\d{0,3})?|1(?:\.0{0,3})?)$/.test(match[1]) ? Number(match[1]) : 0;
+    }
+    if (quality > bestQuality) {
+      language = tag.trim().split("-")[0];
+      bestQuality = quality;
+    }
+  }
+  return language;
+}
